package ug.audiocity.studio;
import java.io.*;import java.nio.*;import java.util.*;
/** Platform-independent exporters: stereo WAV (16/24-bit, TPDF dither), lossless FLAC, per-track stems and loudness normalisation. */
public final class Export {
 private Export(){}
 public static long tailFrames(Core.Session s){double seconds=3;java.util.ArrayList<Core.Track> all=new java.util.ArrayList<>(s.tracks);all.addAll(s.buses);for(Core.Track t:all)if(!t.bypassFx&&t.fx.delay&&t.fx.delayMix>0){Core.Fx f=t.fx;double l=f.delaySync?60.0/s.bpm*f.leftBeats:f.leftMs/1000,r=f.delaySync?60.0/s.bpm*f.rightBeats:f.rightMs/1000,cycle=f.pingPong?l+r:Math.max(l,r),repeats=f.delayFeedback>0?Math.ceil(Math.log(.001)/Math.log(Math.max(.001,f.delayFeedback))):1;seconds=Math.max(seconds,Math.min(15,cycle*(repeats+1)));}return (long)(seconds*Core.RATE);}
 public static void wav(OutputStream target,Core.Session s,int bits)throws Exception {if(bits!=16&&bits!=24)throw new IOException("Use 16-bit or 24-bit PCM.");int sampleBytes=bits/8,frameBytes=sampleBytes*2;long frames=Math.min(Core.MAX_FRAMES,s.end()+tailFrames(s));BufferedOutputStream out=new BufferedOutputStream(target);ByteBuffer header=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);header.put("RIFF".getBytes("US-ASCII")).putInt((int)(36+frames*frameBytes)).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)2).putInt(Core.RATE).putInt(Core.RATE*frameBytes).putShort((short)frameBytes).putShort((short)bits).put("data".getBytes("US-ASCII")).putInt((int)(frames*frameBytes));out.write(header.array());byte[] pcm=new byte[512*frameBytes];Random dither=new Random(902);double scale=Math.pow(2,bits-1);Pro.renderOffline(s,frames,(block,n)->{for(int i=0;i<n*2;i++){double noise=(dither.nextDouble()-dither.nextDouble())/scale;int value=(int)Math.round(Math.max(-1,Math.min(1-1/scale,block[i]+noise))*scale);for(int k=0;k<sampleBytes;k++)pcm[i*sampleBytes+k]=(byte)(value>>(8*k));}out.write(pcm,0,n*frameBytes);});out.flush();}
 /** Lossless FLAC master with the same TPDF dither as WAV export. */
 public static void flac(OutputStream target,Core.Session s,int bits)throws Exception{long frames=Math.min(Core.MAX_FRAMES,s.end()+tailFrames(s));Random dither=new Random(902);double scale=Math.pow(2,bits-1);BufferedOutputStream out=new BufferedOutputStream(target);Pro.FlacWriter w=new Pro.FlacWriter(out,bits,frames);Pro.renderOffline(s,frames,(block,n)->{for(int i=0;i<n;i++){int l=quantise(block[2*i],dither,scale),r=quantise(block[2*i+1],dither,scale);w.sample(l,r);}});w.close();out.flush();}
 static int quantise(double x,Random dither,double scale){double noise=(dither.nextDouble()-dither.nextDouble())/scale;return (int)Math.round(Math.max(-1,Math.min(1-1/scale,x+noise))*scale);}
 /** Writes a ZIP of one file per unmuted track (post-fader, with its sends' buses, master processing bypassed). */
 public static int stems(OutputStream target,Core.Session s,int bits,boolean flac)throws Exception{return stems(target,s,bits,flac,Core.RATE);}
 public static int stems(OutputStream target,Core.Session s,int bits,boolean flac,int rate)throws Exception{java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(new BufferedOutputStream(target));int count=0;HashSet<String> used=new HashSet<>();for(int i=0;i<s.tracks.size();i++){Core.Track t=s.tracks.get(i);if(t.mute||t.clips.isEmpty())continue;String base=String.format(Locale.ROOT,"%02d %s",i+1,t.name.replaceAll("[^a-zA-Z0-9 _-]","").trim());if(base.trim().isEmpty())base=String.format(Locale.ROOT,"%02d Track",i+1);String name=base+(flac?".flac":".wav");int k=2;while(!used.add(name))name=base+" "+(k++)+(flac?".flac":".wav");zip.putNextEntry(new java.util.zip.ZipEntry(name));Core.Session stem=Pro.stem(s,i);OutputStream entry=new FilterOutputStream(zip){public void close(){}public void write(byte[] b,int o,int n)throws IOException{out.write(b,o,n);}};if(flac)flac(entry,stem,bits,rate,true);else wav(entry,stem,bits,rate,true);zip.closeEntry();count++;}if(count==0)throw new IOException("No unmuted tracks with audio to export.");zip.finish();zip.flush();return count;}
 /** A copy of the session with the master fader adjusted so the export reaches targetLufs without its true peak exceeding ceilingDb. Returns null when the mix is silent. */
 public static Core.Session normalised(Core.Session s,double targetLufs,double ceilingDb,double[] report)throws IOException{long frames=Math.min(Core.MAX_FRAMES,s.end()+tailFrames(s));Pro.Loudness m=Pro.analyse(s,frames);if(!Double.isFinite(m.integrated()))return null;double gain=Pro.normaliseGain(m,targetLufs,ceilingDb);Core.Session c=s.copy();c.master=Math.max(0,Math.min(4,s.master*Pro.gain(gain)));if(c.masterAutomation!=null){Pro.Lane l=c.masterAutomation;long[] f=new long[l.size()];double[] v=new double[l.size()];for(int i=0;i<f.length;i++){f[i]=l.frame(i);v[i]=l.value(i)*Pro.gain(gain);}l.set(f,v);}if(report!=null&&report.length>=3){report[0]=m.integrated();report[1]=m.truePeakDb;report[2]=gain;}return c;}
 /** Interleaved stereo frames at the export rate. */
 interface Frames{void frame(double l,double r)throws IOException;}
 /** Renders the session (look-ahead compensated) at 48 kHz or resampled to 44.1 kHz. Returns the number of frames produced. */
 static long render(Core.Session s,int rate,Frames sink)throws IOException{long frames=Math.min(Core.MAX_FRAMES,s.end()+tailFrames(s));if(rate==Core.RATE){Pro.renderOffline(s,frames,(b,n)->{for(int i=0;i<n;i++)sink.frame(b[2*i],b[2*i+1]);});return frames;}
  ProEdit.Resampler r=new ProEdit.Resampler(Core.RATE,rate,sink::frame);Pro.renderOffline(s,frames,(b,n)->{for(int i=0;i<n;i++)r.push(b[2*i],b[2*i+1]);});r.finish(frames);return ProEdit.Resampler.outputFrames(frames,Core.RATE,rate);}
 static long frames(Core.Session s,int rate){long f=Math.min(Core.MAX_FRAMES,s.end()+tailFrames(s));return rate==Core.RATE?f:ProEdit.Resampler.outputFrames(f,Core.RATE,rate);}
 /** WAV at 44.1 or 48 kHz, 16 or 24 bit, with or without TPDF dither. 48 kHz with dither is identical to {@link #wav(OutputStream,Core.Session,int)}. */
 public static void wav(OutputStream target,Core.Session s,int bits,int rate,boolean dither)throws Exception{if(rate==Core.RATE&&dither){wav(target,s,bits);return;}if(bits!=16&&bits!=24)throw new IOException("Use 16-bit or 24-bit PCM.");if(rate!=44100&&rate!=48000)throw new IOException("Use 44.1 or 48 kHz.");int sampleBytes=bits/8,frameBytes=sampleBytes*2;long frames=frames(s,rate);BufferedOutputStream out=new BufferedOutputStream(target);ByteBuffer header=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);header.put("RIFF".getBytes("US-ASCII")).putInt((int)(36+frames*frameBytes)).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)2).putInt(rate).putInt(rate*frameBytes).putShort((short)frameBytes).putShort((short)bits).put("data".getBytes("US-ASCII")).putInt((int)(frames*frameBytes));out.write(header.array());Random noise=dither?new Random(902):null;double scale=Math.pow(2,bits-1);byte[] pcm=new byte[frameBytes];long[] count={0};render(s,rate,(l,r)->{if(count[0]>=frames)return;int a=quant(l,noise,scale),b=quant(r,noise,scale);for(int k=0;k<sampleBytes;k++){pcm[k]=(byte)(a>>(8*k));pcm[sampleBytes+k]=(byte)(b>>(8*k));}out.write(pcm);count[0]++;});while(count[0]<frames){out.write(new byte[frameBytes]);count[0]++;}out.flush();}
 public static void flac(OutputStream target,Core.Session s,int bits,int rate,boolean dither)throws Exception{if(rate==Core.RATE&&dither){flac(target,s,bits);return;}long frames=frames(s,rate);Random noise=dither?new Random(902):null;double scale=Math.pow(2,bits-1);BufferedOutputStream out=new BufferedOutputStream(target);Pro.FlacWriter w=new Pro.FlacWriter(out,bits,frames,rate);long[] count={0};render(s,rate,(l,r)->{if(count[0]>=frames)return;w.sample(quant(l,noise,scale),quant(r,noise,scale));count[0]++;});while(count[0]<frames){w.sample(0,0);count[0]++;}w.close();out.flush();}
 static int quant(double x,Random dither,double scale){double n=dither==null?0:(dither.nextDouble()-dither.nextDouble())/scale;return (int)Math.round(Math.max(-1,Math.min(1-1/scale,x+n))*scale);}
}
